        val args = json.encodeToString(SetKindArgs.serializer(), SetKindArgs(doc, block, kind))
        transport.execute("set_kind", args)
    }

    /**
     * split_block
     *
     * Splits a block in two at a text position and returns the new block, which holds the text after the split and follows the original.
     * Not idempotent: a retry after a lost response splits again, so read the blocks before repeating.
     * Positions count Unicode scalar values, not bytes or UTF-16 units.
     *
     * Write (`mutating`): sent with `execute`.
     *
     * @param doc The document id.
     * @param block The block to split.
     * @param at The position to split at; the text from here on moves to the new block.
     * @return The new block's id.
     */
    suspend fun splitBlock(doc: String, block: String, at: UInt): String {
        val args = json.encodeToString(SplitBlockArgs.serializer(), SplitBlockArgs(doc, block, at))
        val response = transport.execute("split_block", args)
        return json.decodeFromString(serializer<String>(), response)
    }

    /**
     * title_anchor_at
     *
     * Returns a cursor for the gap at a title position, as an opaque token that survives concurrent edits and that any member can resolve.
     * Positions count Unicode scalar values, not bytes or UTF-16 units.
     *
     * View (`read_only`): sent with `query`.
     *
     * @param doc The document id.
     * @param position The gap, counted from 0 at the start of the title.
     * @param before Which side the anchor leans toward when text is inserted exactly at the gap.
     * @return An opaque anchor token.
     */
    suspend fun titleAnchorAt(doc: String, position: UInt, before: Boolean): String {
        val args = json.encodeToString(TitleAnchorAtArgs.serializer(), TitleAnchorAtArgs(doc, position, before))
        val response = transport.query("title_anchor_at", args)
        return json.decodeFromString(serializer<String>(), response)
    }

    /**
     * title_apply_delta
     *
     * Applies one editing transaction to a document's title and returns a token that `title_undo` takes.
     * `ops` is a list of steps that walk the text as it was before the change: `{"retain": 3, "attributes": null}` keeps three characters, `{"insert": "text", "attributes": null}` adds text, `{"delete": 2}` removes two.
     * Text after the last step is kept.
     * The title carries no formatting, so a step with non-null `attributes` is refused.
     * A transaction that leaves the title longer than 1024 characters is refused.
     * Positions count Unicode scalar values, not bytes or UTF-16 units.
     *
     * Write (`mutating`): sent with `execute`.
     *
     * @param doc The document id.
     * @param ops The steps of the transaction, in order.
     * @return An opaque undo token.
     */
    suspend fun titleApplyDelta(doc: String, ops: List<Change>): String {
        val args = json.encodeToString(TitleApplyDeltaArgs.serializer(), TitleApplyDeltaArgs(doc, ops))
        val response = transport.execute("title_apply_delta", args)
        return json.decodeFromString(serializer<String>(), response)
    }

    /**
     * title_apply_delta_on
     *
     * Like `title_apply_delta`, but only applies when the title is still exactly `base`, because a position counted in any other text names the wrong place.
     * When `anchor` is given the write must also be an insert right where that anchor sits.
     * On refusal nothing is written: `applied` is `false` and `text` is the current title to rebase onto.
     *
     * Write (`mutating`): sent with `execute`.
     *
     * @param doc The document id.
     * @param base The full title text the steps were computed against.
     * @param ops The steps of the transaction, as for `title_apply_delta`.
     * @param anchor Optional cursor token from `title_anchor_at`; `null` for an unanchored write.
     * @return Whether the write applied, the undo token, the resulting title, and an anchor at the end of the edit.
     */
    suspend fun titleApplyDeltaOn(doc: String, base: String, ops: List<Change>, anchor: String? = null): TitleApplied {
        val args = json.encodeToString(TitleApplyDeltaOnArgs.serializer(), TitleApplyDeltaOnArgs(doc, base, ops, anchor))
        val response = transport.execute("title_apply_delta_on", args)
        return json.decodeFromString(serializer<TitleApplied>(), response)
    }

    /**
     * title_resolve
     *
     * Returns where anchors currently sit in this node's copy of the title.
     *
     * View (`read_only`): sent with `query`.
     *
     * @param doc The document id.
     * @param anchors Tokens from `title_anchor_at`.
     * @return One position per anchor, in order; `null` for an anchor this node cannot place yet.
     */
    suspend fun titleResolve(doc: String, anchors: List<String>): List<UInt> {
        val args = json.encodeToString(TitleResolveArgs.serializer(), TitleResolveArgs(doc, anchors))
        val response = transport.query("title_resolve", args)
        return json.decodeFromString(serializer<List<UInt>>(), response)
    }

    /**
     * title_undo
     *
     * Takes a whole title transaction back and returns a token that redoes it.
     *
     * Write (`mutating`): sent with `execute`.
     *
     * @param doc The document id.
     * @param token The token `title_apply_delta` (or a previous undo) returned.
     * @return An opaque token that redoes the transaction.
     */
    suspend fun titleUndo(doc: String, token: String): String {
        val args = json.encodeToString(TitleUndoArgs.serializer(), TitleUndoArgs(doc, token))
        val response = transport.execute("title_undo", args)
        return json.decodeFromString(serializer<String>(), response)
    }

    /**
     * unarchive_doc
     *
     * Restores an archived document to the default `list_docs` view.
     *
     * Write (`mutating`): sent with `execute`.
     *
     * @param id The document id.
     */
    suspend fun unarchiveDoc(id: String) {
        val args = json.encodeToString(UnarchiveDocArgs.serializer(), UnarchiveDocArgs(id))
        transport.execute("unarchive_doc", args)
    }

    /**
     * undo
     *
     * Takes a whole text transaction back and returns a token that redoes it.
     *
     * Write (`mutating`): sent with `execute`.
     *
     * @param doc The document id.
     * @param block The block the transaction was applied to.
     * @param token The token `apply_delta` (or a previous undo) returned.
     * @return An opaque token that redoes the transaction.
     */
    suspend fun undo(doc: String, block: String, token: String): String {
        val args = json.encodeToString(UndoArgs.serializer(), UndoArgs(doc, block, token))
        val response = transport.execute("undo", args)
        return json.decodeFromString(serializer<String>(), response)
    }

